// Per-vendor field config (VendorFieldConfig) end to end against a real MongoDB:
// the management script, hidden codes doing their job silently (always
// auto-generated, even when Company Settings says "manual"), the vendor's custom
// fields through the form path, bulk upload / update and the product export.
//
// Uses its own throwaway database - the MONGODB_URI database name with
// "-field-config-test" appended - and drops it afterwards. Skipped when
// MongoDB isn't reachable.
require('dotenv').config({ quiet: true });
process.env.IS_REDIS_SERVER_ON = '0';

const test = require('node:test');
const assert = require('node:assert/strict');
const path = require('path');
const fs = require('fs');
const os = require('os');
const { execFileSync } = require('child_process');
const mongoose = require('mongoose');
const ExcelJS = require('exceljs');

const Product = require('../models/Product');
const SizeMaster = require('../models/SizeMaster');
const Vendor = require('../models/Vendor');
const productService = require('../services/productService');
const productExportService = require('../services/productExportService');
const fieldConfigService = require('../services/fieldConfigService');
const { extractZipEntries } = require('../utils/zipExtractor');

const id = () => new mongoose.Types.ObjectId();
const ADMIN = id();
const DOMAIN = 'field-config.test';
const BACKEND_DIR = path.join(__dirname, '..');
const EXAMPLE_CONFIG = path.join(BACKEND_DIR, 'seeds', 'fieldConfigs', 'example.json');

const websiteMasterData = {};
// The vendor's own setting says "enter codes manually" - hiding the codes must override it.
const manualCodeSettings = { isProductCodeAutoGenerated: false, isVariantCodeAutoGenerated: false, isSizeCodeAutoGenerated: false };
let companyMasterData;
let vendorId;
let fieldConfigData;
let companySettingsData;

const testDbUri = () => {
    const uri = new URL(process.env.MONGODB_URI);
    uri.pathname = `${uri.pathname.replace(/^\//, '') || 'test'}-field-config-test`;
    return uri.toString();
};

let connected = false;

const runScript = (...args) => execFileSync(process.execPath, [path.join('scripts', 'manageVendorFieldConfig.js'), ...args], {
    cwd: BACKEND_DIR,
    env: { ...process.env, MONGODB_URI: testDbUri(), IS_REDIS_SERVER_ON: '0' },
    encoding: 'utf8',
    stdio: ['ignore', 'pipe', 'pipe']
});

test.before(async () => {
    try {
        await mongoose.connect(testDbUri(), { serverSelectionTimeoutMS: 3000 });
        connected = mongoose.connection.db.databaseName.endsWith('-field-config-test');
    } catch (err) {
        connected = false;
    }
    if (!connected) return;
    await mongoose.connection.db.dropDatabase();
    await Product.init();

    const vendor = await Vendor.create({ domain: DOMAIN, email: 'vendor@field-config.test' });
    vendorId = vendor._id;
    const shirtSize = await SizeMaster.create({ name: 'Shirt Size', type: 'LABEL', values: ['S', 'M', 'L'] });
    companyMasterData = { allowedSizes: [shirtSize._id], allowedCountries: [] };
});

test.after(async () => {
    if (connected) await mongoose.connection.db.dropDatabase();
    await mongoose.disconnect();
});

const skipUnlessDb = (t) => {
    if (!connected) t.skip('MongoDB not reachable');
    return !connected;
};

const buildWorkbook = async (mode, rowsBySheet) => {
    const sample = await productService.buildBulkProductSampleFile(mode, fieldConfigData);
    const wb = new ExcelJS.Workbook();
    await wb.xlsx.load(sample.meta.buffer);
    for (const [sheetName, rows] of Object.entries(rowsBySheet)) {
        const sheet = wb.getWorksheet(sheetName);
        const headings = sheet.getRow(1).values;
        for (const row of rows) {
            for (const heading of Object.keys(row)) assert.ok(headings.includes(heading), `${sheetName} has no "${heading}" column`);
            sheet.addRow(headings.map((heading) => (heading in row ? row[heading] : null)));
        }
    }
    return Buffer.from(await wb.xlsx.writeBuffer());
};

const headingsOf = async (buffer, sheetName) => {
    const wb = new ExcelJS.Workbook();
    await wb.xlsx.load(buffer);
    return wb.getWorksheet(sheetName).getRow(1).values.filter(Boolean);
};

const variantRow = (variantTempCode, productTempCode, extra = {}) => ({
    'VariantTempCode*': variantTempCode, 'ProductTempCode*': productTempCode, 'IsDefaultVariant*': true, Color: 'Red',
    'IsDescriptionSameFromProductBasicDetails*': true, 'IsDisclaimerSameFromProductBasicDetails*': true, 'IsBulkPricingSameFromProductBasicDetails*': true,
    ...extra
});

const sizeRow = (sizeTempCode, variantTempCode, labelValue, sku, extra = {}) => ({
    'SizeTempCode*': sizeTempCode, 'VariantTempCode*': variantTempCode, 'IsDefaultSize*': false, 'SizeType*': 'LABEL',
    'SizeMasterName*': 'shirt size', 'SizeName*': `Size ${labelValue}`, LabelValue: labelValue, 'Price*': 100, 'SKU*': sku,
    'IsDescriptionSameFromVariantsDetails*': true, 'IsDisclaimerSameFromVariantsDetails*': true, 'IsBulkPricingSameFromVariantsDetails*': true,
    'WarrantyAvailable*': false, 'ReturnAvailable*': false, 'ExchangeAvailable*': false, 'ShippingType*': 'COMPANY_SETTINGS',
    ...extra
});

const runBulk = (fn, buffer) => fn(vendorId, ADMIN, buffer, null, null, companyMasterData, websiteMasterData, companySettingsData, null, fieldConfigData);
const failures = (result) => result.meta.failedRecords.map((r) => `${r.data.name}: ${r.errors.join('; ')}`);
const findProduct = (name) => Product.findOne({ vendorId, name }).lean();
const valuesOf = (product) => Object.fromEntries((product.customFieldValues || []).map((e) => [e.key, e.value]));

const formBody = (name, sku, extra = {}) => ({
    name,
    colors: ['Red'],
    variants: [{
        isDefaultVariant: true, color: 'Red',
        isDescriptionSameFromProductBasicDetails: true, isDisclaimerSameFromProductBasicDetails: true, isBulkPricingSameFromProductBasicDetails: true,
        sizes: [{
            isDefaultSize: true, sizeType: 'LABEL', sizeId: String(companyMasterData.allowedSizes[0]), sizeName: 'Size S', labelValue: 'S',
            price: 100, sku,
            isDescriptionSameFromVariantsDetails: true, isDisclaimerSameFromVariantsDetails: true, isBulkPricingSameFromVariantsDetails: true,
            warranty: { isAvailable: false }, return: { isAvailable: false }, exchange: { isAvailable: false },
            shipping: { type: 'COMPANY_SETTINGS' }
        }]
    }],
    ...extra
});

test('script: an invalid file is refused, the example config is saved and read back', async (t) => {
    if (skipUnlessDb(t)) return;

    const badFile = path.join(os.tmpdir(), `bad-field-config-${Date.now()}.json`);
    fs.writeFileSync(badFile, JSON.stringify({ product: { hiddenFields: ['name'], customFields: [] } }));
    assert.throws(() => runScript('set', DOMAIN, badFile), /hiddenFields\[0\]/);
    fs.unlinkSync(badFile);
    assert.deepEqual(await fieldConfigService.fetchVendorFieldConfig(vendorId), {});

    const output = runScript('set', DOMAIN, EXAMPLE_CONFIG);
    assert.match(output, /Field config saved/);
    assert.match(output, /boxCode "Box Code"/);

    fieldConfigData = await fieldConfigService.fetchVendorFieldConfig(vendorId);
    assert.deepEqual(fieldConfigData.product.hiddenFields, ['productCode', 'variantCode', 'sizeCode']);
    assert.deepEqual(fieldConfigData.product.customFields.map((cf) => cf.key), ['packetCode', 'sapCode', 'boxCode']);

    // What loadVendorFieldConfig hands the services.
    companySettingsData = fieldConfigService.applyHiddenFieldSettings(manualCodeSettings, fieldConfigData);
    assert.equal(companySettingsData.isProductCodeAutoGenerated, true);
    assert.equal(companySettingsData.isVariantCodeAutoGenerated, true);
    assert.equal(companySettingsData.isSizeCodeAutoGenerated, true);
    assert.equal(manualCodeSettings.isProductCodeAutoGenerated, false, 'the cached settings object is not modified');
});

test('form path: hidden codes are auto-generated, custom values are checked, unknown keys dropped, left out = kept', async (t) => {
    if (skipUnlessDb(t)) return;

    const created = await productService.createProduct(vendorId, ADMIN, companyMasterData, websiteMasterData, companySettingsData,
        formBody('Form Tee', 'FORM-S', { customFieldValues: [{ key: 'packetCode', value: ' PK-9 ' }, { key: 'nope', value: 'x' }, { key: 'boxCode', value: '' }] }),
        [], fieldConfigData);
    assert.equal(created.isSuccess, true, created.message);

    let tee = await findProduct('Form Tee');
    assert.match(tee.productCode, /^PRD-\d{6}$/);
    assert.match(tee.variants[0].variantCode, /^VAR-\d{6}$/);
    assert.match(tee.variants[0].sizes[0].sizeCode, /^SIZ-\d{6}$/);
    assert.deepEqual(valuesOf(tee), { packetCode: 'PK-9' });

    // An update that does not send customFieldValues leaves them alone.
    const updateBody = (extra) => ({
        ...formBody('Form Tee', 'FORM-S'),
        productId: String(tee._id),
        variants: [{ ...formBody('x', 'FORM-S').variants[0], _id: String(tee.variants[0]._id),
            sizes: [{ ...formBody('x', 'FORM-S').variants[0].sizes[0], _id: String(tee.variants[0].sizes[0]._id) }] }],
        ...extra
    });
    let updated = await productService.updateProduct(vendorId, ADMIN, companyMasterData, websiteMasterData, companySettingsData, updateBody({}), [], fieldConfigData);
    assert.equal(updated.isSuccess, true, updated.message);
    assert.deepEqual(valuesOf(await findProduct('Form Tee')), { packetCode: 'PK-9' });

    updated = await productService.updateProduct(vendorId, ADMIN, companyMasterData, websiteMasterData, companySettingsData,
        updateBody({ customFieldValues: [{ key: 'sapCode', value: 4455 }, { key: 'boxCode', value: 'BX-1' }] }), [], fieldConfigData);
    assert.equal(updated.isSuccess, true, updated.message);
    tee = await findProduct('Form Tee');
    assert.deepEqual(valuesOf(tee), { sapCode: '4455', boxCode: 'BX-1' });

    // The Edit form and the admin list read them back (storefront reads never get them).
    const forEdit = await productService.fetchProductByIdForAdmin(vendorId, tee._id);
    assert.deepEqual(valuesOf(forEdit.meta.product), { sapCode: '4455', boxCode: 'BX-1' });
    const adminList = await productService.fetchAllProductsForAdmin(vendorId, { q: 'Form Tee' }, { companySettingsData });
    assert.deepEqual(valuesOf(adminList.meta.products.find((p) => p.name === 'Form Tee')), { sapCode: '4455', boxCode: 'BX-1' });
    assert.equal(tee.variants[0].sizes[0].sizeCode !== undefined, true);

    // Required / select checks.
    const strict = { product: { ...fieldConfigData.product, customFields: [
        { key: 'grade', label: 'Grade', type: 'select', options: ['A', 'B'], required: true, placement: { mode: 'end', field: null } }
    ] } };
    assert.equal(fieldConfigService.normalizeCustomFieldValues(strict, 'product', []).message, 'Grade is required.');
    assert.equal(fieldConfigService.normalizeCustomFieldValues(strict, 'product', [{ key: 'grade', value: 'c' }]).isSuccess, false);
    assert.deepEqual(fieldConfigService.normalizeCustomFieldValues(strict, 'product', [{ key: 'grade', value: 'b' }]).meta.customFieldValues, [{ key: 'grade', value: 'B' }]);
});

test('bulk upload: no code columns, custom field columns, recommended products by name, codes auto-generated', async (t) => {
    if (skipUnlessDb(t)) return;

    const sample = await productService.buildBulkProductSampleFile('upload', fieldConfigData);
    const productHeadings = await headingsOf(sample.meta.buffer, 'Products');
    assert.ok(!productHeadings.includes('ProductCode'));
    assert.ok(!productHeadings.includes('RecommendedProductCodes'));
    assert.ok(productHeadings.includes('RecommendedProductNames'));
    for (const heading of ['Packet Code', 'SAP Code', 'Box Code']) assert.ok(productHeadings.includes(heading), heading);
    assert.ok(!(await headingsOf(sample.meta.buffer, 'Variants')).includes('VariantCode'));
    assert.ok(!(await headingsOf(sample.meta.buffer, 'Sizes')).includes('SizeCode'));

    const buffer = await buildWorkbook('upload', {
        Products: [
            { 'ProductTempCode*': 'P1', 'Name*': 'Bulk Polo', 'Colors*': 'Red', 'Packet Code': 'PK-1', 'SAP Code': 7788 },
            { 'ProductTempCode*': 'P2', 'Name*': 'Bulk Shirt', 'Colors*': 'Red', 'Box Code': 'BX-2', RecommendedProductNames: 'form tee' },
            { 'ProductTempCode*': 'P3', 'Name*': 'Bulk Ghost', 'Colors*': 'Red', RecommendedProductNames: 'Missing Product' }
        ],
        Variants: [variantRow('V1', 'P1'), variantRow('V2', 'P2'), variantRow('V3', 'P3')],
        Sizes: [sizeRow('S1', 'V1', 'S', 'POLO-S'), sizeRow('S2', 'V2', 'M', 'SHIRT-M'), sizeRow('S3', 'V3', 'M', 'GHOST-M')]
    });

    const result = await runBulk(productService.bulkUploadProducts, buffer);
    assert.equal(result.isSuccess, true);
    assert.deepEqual(failures(result), ['Bulk Ghost: Recommended product(s) not found: Missing Product']);

    const polo = await findProduct('Bulk Polo');
    assert.match(polo.productCode, /^PRD-\d{6}$/);
    assert.match(polo.variants[0].variantCode, /^VAR-\d{6}$/);
    assert.match(polo.variants[0].sizes[0].sizeCode, /^SIZ-\d{6}$/);
    assert.deepEqual(valuesOf(polo), { packetCode: 'PK-1', sapCode: '7788' });

    const shirt = await findProduct('Bulk Shirt');
    const formTee = await findProduct('Form Tee');
    assert.deepEqual(shirt.recommendedProducts.map(String), [String(formTee._id)]);
    assert.deepEqual(valuesOf(shirt), { boxCode: 'BX-2' });
});

test('bulk update + export: code columns kept as references, blank keeps / CLEAR empties custom values', async (t) => {
    if (skipUnlessDb(t)) return;

    const updateSample = await productService.buildBulkProductSampleFile('update', fieldConfigData);
    assert.ok((await headingsOf(updateSample.meta.buffer, 'Variants')).includes('VariantCode'));
    assert.ok((await headingsOf(updateSample.meta.buffer, 'Sizes')).includes('SizeCode'));
    assert.ok(!(await headingsOf(updateSample.meta.buffer, 'Products')).includes('ProductCode'));

    const before = await findProduct('Bulk Polo');
    const buffer = await buildWorkbook('update', {
        Products: [{ 'ProductTempCode*': 'P1', 'Name*': 'bulk polo', 'SAP Code': 'CLEAR', 'Box Code': 'BX-NEW' }],
        Variants: [variantRow('V1', 'P1', { VariantCode: before.variants[0].variantCode })],
        Sizes: [sizeRow('S1', 'V1', 'S', 'POLO-S', { SizeCode: before.variants[0].sizes[0].sizeCode, 'Price*': 120 })]
    });
    const result = await runBulk(productService.bulkUpdateProducts, buffer);
    assert.deepEqual(failures(result), []);

    const polo = await findProduct('Bulk Polo');
    assert.deepEqual(valuesOf(polo), { packetCode: 'PK-1', boxCode: 'BX-NEW' });
    assert.equal(String(polo.variants[0].sizes[0]._id), String(before.variants[0].sizes[0]._id));
    assert.equal(polo.variants[0].sizes[0].price, 120);
    assert.equal(polo.productCode, before.productCode);

    // Export: the file the vendor downloads can be uploaded straight back.
    const exported = await productExportService.buildProductExport(vendorId, { ids: [String(polo._id), String((await findProduct('Bulk Shirt'))._id)] },
        { websiteMasterData, companyMasterData, companySettingsData, fieldConfigData });
    assert.equal(exported.isSuccess, true, exported.message);
    try {
        const entries = extractZipEntries(fs.readFileSync(exported.meta.filePath));
        const excelEntry = [...entries.entries()].find(([name]) => name.endsWith('.xlsx'));
        const wb = new ExcelJS.Workbook();
        await wb.xlsx.load(excelEntry[1]);
        const sheet = wb.getWorksheet('Products');
        const headings = sheet.getRow(1).values;
        const rows = [];
        sheet.eachRow((row, n) => { if (n > 1) rows.push(Object.fromEntries(headings.map((h, i) => [h, row.getCell(i).value]).filter(([h]) => h))); });
        assert.ok(!headings.includes('ProductCode'));
        const poloRow = rows.find((r) => r['Name*'] === 'Bulk Polo');
        assert.equal(poloRow['Packet Code'], 'PK-1');
        assert.equal(poloRow['Box Code'], 'BX-NEW');
        const shirtRow = rows.find((r) => r['Name*'] === 'Bulk Shirt');
        assert.equal(shirtRow.RecommendedProductNames, 'Form Tee');
        assert.ok(wb.getWorksheet('Variants').getRow(1).values.includes('VariantCode'));
    } finally {
        await productExportService.removeExportFile(exported.meta.filePath);
    }
});

test('script: remove gives the vendor the standard fields back', async (t) => {
    if (skipUnlessDb(t)) return;

    const output = runScript('remove', DOMAIN, 'product');
    assert.match(output, /removed/);
    assert.deepEqual(await fieldConfigService.fetchVendorFieldConfig(vendorId), {});
    const sample = await productService.buildBulkProductSampleFile('upload', {});
    assert.ok((await headingsOf(sample.meta.buffer, 'Products')).includes('ProductCode'));
});
